const { mkdirSync, writeFileSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
const { mkdtempSync, rmSync } = await import('node:fs');
const tempRoot = mkdtempSync(join(tmpdir(), 'koala-role-mixed-'));
try {
  mkdirSync(join(tempRoot, 'docs', 'story'), { recursive: true });
  writeFileSync(join(tempRoot, 'docs', 'story', 'activity.jsonl'), [
    JSON.stringify({ source: 'codex', tool: 'session_brief', status: 'ok', endTime: new Date().toISOString() }),
    JSON.stringify({ source: 'codex', role: 'reviewer', tool: 'session_brief', status: 'ok', endTime: new Date().toISOString() })
  ].join('
') + '
');
  const mod = await import($file);
  const res = mod.createToolStatusHandlers({ root: tempRoot }).tool_status({ source: 'codex', days: 1, format: 'json' });
  return {
    unknownSeen: (res.summary.byRole?.unknown || 0) === 1,
    reviewerSeen: (res.summary.byRole?.reviewer || 0) === 1
  };
} finally { rmSync(tempRoot, { recursive: true, force: true }); }

