const { mkdirSync, writeFileSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
const { mkdtempSync, rmSync } = await import('node:fs');
const tempRoot = mkdtempSync(join(tmpdir(), 'koala-stale-old-'));
try {
  mkdirSync(join(tempRoot, 'docs', 'story', 'actives', 'B-test'), { recursive: true });
  writeFileSync(join(tempRoot, 'koala.config.json'), JSON.stringify({ storyDir: 'docs/story/actives', requirementsDir: 'docs/requirements', scanRoot: 'src', testsDir: 'tests', fixturesDir: 'tests/fixtures', storyPrefix: 'B' }));
  writeFileSync(join(tempRoot, 'docs', 'story', 'activity.jsonl'), JSON.stringify({ source: 'codex', tool: 'session_brief', status: 'ok', endTime: new Date(Date.now() - 2 * 3600 * 1000).toISOString() }) + '
');
  writeFileSync(join(tempRoot, 'docs', 'story', 'actives', 'B-test', 'index.json'), JSON.stringify({ storyId: 'B-test', name: 'tmp', title: 'tmp', description: 'tmp', type: 'feature', phase: 'DEV', priority: 'high', createdAt: new Date().toISOString(), startedAt: new Date().toISOString(), endedAt: null, events: [{ phase: 'DEV', action: 'advance', timestamp: new Date(Date.now() - 2 * 3600 * 1000).toISOString() }] }));
  writeFileSync(join(tempRoot, 'docs', 'story', 'actives', 'B-test', 'checklist.json'), JSON.stringify({ items: [] }));
  writeFileSync(join(tempRoot, 'docs', 'story', 'actives', 'B-test', 'bug.json'), JSON.stringify({ bugs: [] }));
  const mod = await import($file);
  const warnings = mod.detectStaleState({ root: tempRoot, store: { readStory: () => JSON.parse(require('fs').readFileSync(join(tempRoot,'docs/story/actives/B-test/index.json'),'utf8')), readChecklist: () => ({ items: [] }), readBugs: () => ({ bugs: [] }) } });
  return { hasIdleWarning: Array.isArray(warnings) && warnings.length >= 1 };
} finally { rmSync(tempRoot, { recursive: true, force: true }); }

